// static
bool StructTraits<::arc::mojom::CompositionSegment::DataView, ::arc::mojom::CompositionSegmentPtr>::Read(
    ::arc::mojom::CompositionSegment::DataView input,
    ::arc::mojom::CompositionSegmentPtr* output) {
  bool success = true;
  ::arc::mojom::CompositionSegmentPtr result(::arc::mojom::CompositionSegment::New());
  
      if (success)
        result->start_offset = input.start_offset();
      if (success)
        result->end_offset = input.end_offset();
      if (success)
        result->emphasized = input.emphasized();
      if (success && !input.ReadStyle(&result->style))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::arc::mojom::KeyEventData::DataView, ::arc::mojom::KeyEventDataPtr>::Read(
    ::arc::mojom::KeyEventData::DataView input,
    ::arc::mojom::KeyEventDataPtr* output) {
  bool success = true;
  ::arc::mojom::KeyEventDataPtr result(::arc::mojom::KeyEventData::New());
  
      if (success)
        result->pressed = input.pressed();
      if (success)
        result->key_code = input.key_code();
      if (success)
        result->is_shift_down = input.is_shift_down();
      if (success)
        result->is_control_down = input.is_control_down();
      if (success)
        result->is_alt_down = input.is_alt_down();
      if (success)
        result->is_capslock_on = input.is_capslock_on();
      if (success)
        result->scan_code = input.scan_code();
      if (success)
        result->is_alt_gr_down = input.is_alt_gr_down();
      if (success)
        result->is_repeat = input.is_repeat();
  *output = std::move(result);
  return success;
}

